// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val, bool _initialized) internal {
        vm.assume(_initialized == c.MinSum() > 0 || !_initialized);
        bool reverted = false;
        try c.SetMinSum(_val) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted != !_initialized);
    }

    function testFuzz_run(uint256 _val, bool _initialized) public {
        _run(_val, _initialized);
    }

    receive() external payable {}
}
